import zipfile, csv, io, sys, math
zip_path = '/workspace/ASE24_data_and_tools.zip'
patterns = 'ASE24_data_and_tools/results_data/execution/'
files = []
with zipfile.ZipFile(zip_path) as z:
    for name in z.namelist():
        if name.startswith(patterns) and name.endswith('executionsData.csv'):
            files.append(name)
    if not files:
        print("ERROR: No executionsData.csv files found", file=sys.stderr)
        sys.exit(1)
    # read and combine rows, dedupe by project name (keep first occurrence)
    rows_by_name = {}
    for f in files:
        with z.open(f) as fh:
            data = fh.read().decode('utf-8', errors='replace')
        rdr = csv.DictReader(io.StringIO(data))
        # normalize header names (strip BOM and whitespace)
        if rdr.fieldnames:
            rdr.fieldnames = [h.strip().lstrip('\ufeff') if h else h for h in rdr.fieldnames]
        for r in rdr:
            # normalize keys similarly
            r = { (k.strip().lstrip('\ufeff') if k else k): v for k,v in r.items() }
            name = r.get('name') or r.get('repoName') or r.get('gitUrl')
            if not name:
                continue
            if name in rows_by_name:
                continue
            rows_by_name[name] = r

rows = list(rows_by_name.values())
if len(rows) == 0:
    print("ERROR: No rows found after combining executionsData.csv files", file=sys.stderr)
    sys.exit(2)

def to_num(x):
    if x is None: return None
    s = str(x).strip().replace(',','')
    if s == '': return None
    try:
        if '.' in s:
            return float(s)
        return int(s)
    except:
        try:
            return float(s)
        except:
            return None

# mapping to required metrics
col_map = {
    "(p)’s direct dependencies": ['directDepNumber','directDep','direct_dep','directDep','directDepNum'],
    "releases ((N_R))": ['releaseSize','release','releases','release_size','releaseSize'],
    "libraries ((N_L))": ['artifactSize','artifactSize','artifact_size','artifact','artifactCount','artifactNumber'],
    "dependency edges ((E_D))": ['dependencySize','dependencySize','dependency_size','dependency','dependencyEdges','depEdge'],
    "versions edges ((E_V))": ['versionSize','versionSize','version_size','version','versionEdges']
}

# detect actual column names present
present_cols = set()
if rows and isinstance(rows[0], dict):
    present_cols = set(rows[0].keys())

resolved = {}
for label, candidates in col_map.items():
    found = None
    for c in candidates:
        # try exact name
        if c in present_cols:
            found = c
            break
    if not found:
        # try case-insensitive contains match
        clower = [p.lower() for p in present_cols]
        for c in candidates:
            for p in present_cols:
                if c.lower() in p.lower():
                    found = p
                    break
            if found: break
    if not found:
        # last resort: try some likely names
        for p in present_cols:
            low = p.lower()
            if 'direct' in low and 'dep' in low:
                found = p; break
            if 'release' in low:
                found = found or p
            if 'artifact' in low or 'library' in low:
                found = found or p
            if 'dependency' in low and 'size' in low:
                found = found or p
            if 'version' in low and 'size' in low:
                found = found or p
    if found:
        resolved[label] = found
    else:
        print("ERROR: Could not find column for", label, "available columns:", sorted(list(present_cols)), file=sys.stderr)
        sys.exit(3)

def quantile(sorted_list, q):
    n = len(sorted_list)
    if n == 0:
        return None
    pos = q*(n-1)
    lo = int(math.floor(pos))
    hi = int(math.ceil(pos))
    if lo == hi:
        return sorted_list[lo]
    frac = pos - lo
    return sorted_list[lo] + frac*(sorted_list[hi] - sorted_list[lo])

results = []
for label, col in resolved.items():
    vals = []
    for r in rows:
        v = to_num(r.get(col))
        if v is not None:
            vals.append(float(v))
    vals.sort()
    if not vals:
        q1=q2=q3=mn=mx = None
    else:
        q1 = quantile(vals, 0.25)
        q2 = quantile(vals, 0.5)
        q3 = quantile(vals, 0.75)
        mn = min(vals)
        mx = max(vals)
    results.append((label, q1, q2, q3, mn, mx))

def fmt(v):
    if v is None: return ''
    if abs(v - round(v)) < 1e-9:
        return str(int(round(v)))
    s = ('{:.6f}'.format(v)).rstrip('0').rstrip('.')
    # show .5 as single decimal
    if '.' in s:
        frac = s.split('.')[1]
        if len(frac) == 1:
            return s
    return s

# write output
out = []
out.append('**Reproduced Table 2**')
out.append('')
out.append('|                           |    Q1 |  Q2 |   Q3 | min |     max |')
out.append('| ------------------------- | ----: | --: | ---: | --: | ------: |')
for row in results:
    label, q1, q2, q3, mn, mx = row
    out.append('| {} | {:>4} | {:>3} | {:>4} | {:>3} | {:>7} |'.format(label, fmt(q1), fmt(q2), fmt(q3), fmt(mn), fmt(mx)))

with open('/workspace/repro.txt','w') as f:
    f.write('\\n'.join(out) + '\\n')

# print inside artisan_submit
print('<artisan_submit>')
print('\\n'.join(out))
print('</artisan_submit>')
